-- ─────────────────────────────────────
-- BLOCK 1: Internal Bylaw Articles
-- ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS bylaw_articles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  chapter_number INTEGER NOT NULL,
  chapter_title VARCHAR(300) NOT NULL,
  article_number INTEGER NOT NULL,
  article_title VARCHAR(300),
  article_content TEXT NOT NULL,
  article_type VARCHAR(30) CHECK (article_type IN (
    'organizational',   -- تنظيمي
    'disciplinary',     -- انضباطي
    'financial',        -- مالي
    'ethical',          -- أخلاقي
    'membership',       -- عضوية
    'activities',       -- نشاطات
    'penalties'         -- عقوبات
  )),
  is_highlighted BOOLEAN DEFAULT false,
  -- مواد تُعرض بتمييز خاص (مهمة جداً)
  display_order INTEGER,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ─────────────────────────────────────
-- BLOCK 2: Bylaw acknowledgments
-- Every user must acknowledge on first login
-- ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS bylaw_acknowledgments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  user_type VARCHAR(20) CHECK (user_type IN (
    'internal','volunteer','donor','beneficiary'
  )),
  acknowledged_at TIMESTAMPTZ DEFAULT NOW(),
  ip_address VARCHAR(45),
  bylaw_version VARCHAR(10) DEFAULT '1.0',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ─────────────────────────────────────
-- BLOCK 3: Login history
-- ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS login_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  user_type VARCHAR(20) CHECK (user_type IN (
    'internal','volunteer','donor','beneficiary'
  )),
  user_name VARCHAR(150),
  user_role VARCHAR(30),
  login_at TIMESTAMPTZ DEFAULT NOW(),
  ip_address VARCHAR(45),
  device_info TEXT,
  session_id VARCHAR(100),
  is_successful BOOLEAN DEFAULT true
);

-- ─────────────────────────────────────
-- BLOCK 4: Bylaw version control
-- ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS bylaw_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  version VARCHAR(10) NOT NULL,
  -- 1.0, 1.1, 2.0 etc
  published_at DATE DEFAULT CURRENT_DATE,
  published_by UUID REFERENCES user_profiles(id),
  change_summary TEXT,
  is_current BOOLEAN DEFAULT true,
  requires_re_acknowledgment BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS
ALTER TABLE bylaw_articles         ENABLE ROW LEVEL SECURITY;
ALTER TABLE bylaw_acknowledgments  ENABLE ROW LEVEL SECURITY;
ALTER TABLE login_history          ENABLE ROW LEVEL SECURITY;
ALTER TABLE bylaw_versions         ENABLE ROW LEVEL SECURITY;

-- All authenticated users can read bylaw
CREATE POLICY "bylaw_read_all" ON bylaw_articles
  FOR SELECT USING (auth.uid() IS NOT NULL AND is_active = true);

-- Only president can modify bylaw
CREATE POLICY "bylaw_manage" ON bylaw_articles
  FOR ALL USING (get_my_role() = 'president');

-- User sees own acknowledgments
CREATE POLICY "ack_own" ON bylaw_acknowledgments
  FOR ALL USING (user_id = auth.uid());

-- Top 3 see all login history
CREATE POLICY "login_history_top" ON login_history
  FOR SELECT USING (
    user_id = auth.uid() OR is_top_management()
  );

CREATE POLICY "bylaw_versions_read" ON bylaw_versions
  FOR SELECT USING (auth.uid() IS NOT NULL);

INSERT INTO bylaw_versions (version, change_summary, is_current)
VALUES ('1.0', 'الإصدار الأول من القانون الداخلي', true);

INSERT INTO bylaw_articles
  (chapter_number, chapter_title, article_number,
   article_title, article_content, article_type,
   is_highlighted, display_order)
VALUES
(1, 'أحكام عامة وتعريفات', 1, 'التسمية والطابع', 'تأسست جمعية غيث الولائية للعمل الخيري والإنساني طبقاً لأحكام القانون رقم 12-06 المؤرخ في 12 يناير 2012 المتعلق بالجمعيات، وهي جمعية ذات طابع خيري إنساني تربوي اجتماعي تعمل في إطار القوانين والتشريعات الجزائرية المعمول بها.', 'organizational', true, 1),
(1, 'أحكام عامة وتعريفات', 2, 'المقر الاجتماعي', 'يقع المقر الاجتماعي للجمعية بولاية المسيلة، ويمكن نقله بقرار من مجلس الإدارة وفق الإجراءات القانونية المعمول بها.', 'organizational', false, 2),
(1, 'أحكام عامة وتعريفات', 3, 'أهداف الجمعية', 'تسعى الجمعية إلى تحقيق الأهداف التالية: أولاً: دعم الأسر المعوزة والأرامل والأيتام بالمساعدات المادية والمعنوية. ثانياً: الاهتمام بذوي الاحتياجات الخاصة وتقديم الرعاية اللازمة لهم. ثالثاً: مساندة أصحاب الأمراض المزمنة وتسهيل حصولهم على الرعاية الصحية. رابعاً: دعم التلاميذ المحتاجين في مسيرتهم الدراسية. خامساً: المساهمة في تنمية روح التضامن والتكافل الاجتماعي بولاية المسيلة.', 'organizational', true, 3),
(2, 'شروط العضوية والانتساب', 4, 'شروط الانخراط', 'يشترط في كل عضو يرغب في الانتساب للجمعية: 1. أن يكون جزائري الجنسية بالغاً سن الرشد القانوني. 2. أن يكون حسن السيرة والسلوك غير محكوم عليه بجريمة مخلة بالشرف. 3. أن يلتزم بأهداف الجمعية وقانونها الأساسي والداخلي. 4. أن يقدم طلب انخراط كتابياً للمكتب التنفيذي. 5. دفع رسم الانخراط السنوي المحدد من الجمعية العامة.', 'membership', true, 4),
(2, 'شروط العضوية والانتساب', 5, 'حقوق الأعضاء', 'يتمتع كل عضو نشيط بالحقوق التالية: 1. حق التصويت في الجمعية العامة. 2. حق الترشح لعضوية المكتب التنفيذي بعد سنة من الانتساب. 3. حق الاطلاع على تقارير الجمعية ومحاضر الاجتماعات. 4. حق تقديم المقترحات والملاحظات البناءة. 5. حق الانسحاب من الجمعية بإشعار كتابي مسبق.', 'membership', false, 5),
(2, 'شروط العضوية والانتساب', 6, 'واجبات الأعضاء', 'يلتزم كل عضو بما يلي: 1. احترام القانون الأساسي والداخلي للجمعية. 2. المشاركة الفعالة في أنشطة الجمعية ونشاطاتها. 3. الحفاظ على سمعة الجمعية وصورتها الحسنة. 4. الحفاظ على سرية المعلومات الداخلية للجمعية وعدم إفشائها لأي جهة كانت. 5. دفع الاشتراك السنوي في الآجال المحددة. 6. الامتثال لقرارات المكتب التنفيذي والجمعية العامة. 7. الإخلاص للعمل الخيري ونبذ المصالح الشخصية.', 'membership', true, 6),
(2, 'شروط العضوية والانتساب', 7, 'فقدان العضوية', 'تُفقد العضوية في الحالات التالية: 1. الوفاة. 2. الاستقالة الطوعية بطلب كتابي. 3. عدم دفع الاشتراك السنوي لمدة سنتين متتاليتين. 4. الغياب غير المبرر عن 3 اجتماعات متتالية. 5. ارتكاب مخالفة تأديبية جسيمة يقررها المكتب. 6. الإدانة بحكم قضائي نهائي في جريمة مخلة بالشرف.', 'membership', false, 7),
(3, 'الهيكل التنظيمي والإداري', 8, 'هياكل الجمعية', 'تتكون الجمعية من الهياكل التالية: أولاً: الجمعية العامة (السلطة العليا). ثانياً: المكتب التنفيذي الولائي (الهيئة التنفيذية). ثالثاً: المكاتب البلدية في كل بلدية ممثَّلة. رابعاً: محافظ الحسابات (جهاز رقابي مستقل).', 'organizational', false, 8),
(3, 'الهيكل التنظيمي والإداري', 9, 'الجمعية العامة', 'الجمعية العامة هي السلطة العليا للجمعية وتختص بـ: 1. المصادقة على التقرير الأدبي والمالي السنوي. 2. انتخاب وعزل أعضاء المكتب التنفيذي. 3. تعديل القانون الأساسي والداخلي. 4. تحديد مبلغ الاشتراك السنوي. 5. البت في حل الجمعية أو دمجها. تنعقد الجمعية العامة مرة واحدة سنوياً على الأقل، وكلما دعت الضرورة لذلك بطلب من ثلث الأعضاء.', 'organizational', false, 9),
(3, 'الهيكل التنظيمي والإداري', 10, 'المكتب التنفيذي — التشكيلة', 'يتكون المكتب التنفيذي الولائي من: 1. رئيس الجمعية — يمثل الجمعية أمام الجهات الرسمية. 2. نائب رئيس الجمعية — يحل محل الرئيس عند غيابه. 3. أمين المال — يسير الشؤون المالية للجمعية. 4. أمين المال المساعد — يعاون أمين المال. 5. الكاتب العام — يتولى الشؤون الإدارية. 6. الكاتب العام المساعد — يعاون الكاتب العام. 7. أعضاء المكتب — يشاركون في اتخاذ القرارات. مدة العهدة: أربع (04) سنوات قابلة للتجديد مرة واحدة.', 'organizational', true, 10),
(3, 'الهيكل التنظيمي والإداري', 11, 'صلاحيات رئيس الجمعية', 'يتمتع رئيس الجمعية بالصلاحيات التالية: 1. تمثيل الجمعية أمام القضاء والإدارة والغير. 2. الإشراف على تنفيذ قرارات المكتب التنفيذي. 3. التوقيع على جميع العقود والوثائق الرسمية. 4. الدعوة لاجتماعات المكتب والجمعية العامة. 5. الموافقة على الصرف المالي وفق الميزانية. 6. تعيين وعزل أعضاء اللجان الفرعية. 7. اتخاذ قرارات استعجالية بين الاجتماعات مع إخطار المكتب لاحقاً.', 'organizational', false, 11),
(3, 'الهيكل التنظيمي والإداري', 12, 'صلاحيات أمين المال', 'يضطلع أمين المال بالمهام التالية: 1. تسيير الأموال النقدية والحسابات البنكية. 2. إعداد الميزانية التقديرية والتقرير المالي. 3. صرف النفقات وفق الاعتمادات المقررة. 4. الاحتفاظ بالوثائق المحاسبية كاملة. 5. تحصيل الاشتراكات والتبرعات. 6. التوقيع المشترك مع الرئيس على الصكوك المالية. 7. تقديم حساب دقيق للجمعية العامة سنوياً.', 'financial', true, 12),
(4, 'الأحكام المالية والمحاسبية', 13, 'موارد الجمعية', 'تتكون موارد الجمعية من: 1. اشتراكات الأعضاء السنوية. 2. التبرعات والهبات والوصايا المشروعة. 3. الإعانات الحكومية والمحلية. 4. عائدات الأنشطة والتظاهرات التي تنظمها. 5. كل مورد مشروع لا يتعارض مع القانون والقيم الوطنية. يُحظر تماماً قبول أي تمويل أجنبي دون الحصول على الموافقة المسبقة للسلطات المختصة طبقاً للمادة 30 من القانون 12-06.', 'financial', true, 13),
(4, 'الأحكام المالية والمحاسبية', 14, 'تسيير الأموال ومبدأ الشفافية', 'تُسيَّر أموال الجمعية وفق المبادئ التالية: 1. كل صرف يتجاوز 5,000 دج يستلزم توقيع الرئيس وأمين المال معاً. 2. تُحفظ جميع الوثائق المالية لمدة 10 سنوات. 3. يُعقد جرد سنوي شامل لممتلكات الجمعية. 4. لا يجوز لأي عضو الاستفادة من أموال الجمعية لأغراض شخصية تحت أي مسمى. 5. يُقدَّم التقرير المالي السنوي للجمعية العامة مرفقاً بتقرير محافظ الحسابات. 6. أي مبالغ مالية مقبوضة تُسلَّم لأمين المال فور استلامها مع وصل رسمي.', 'financial', true, 14),
(4, 'الأحكام المالية والمحاسبية', 15, 'الاستفادات والمساعدات', 'تُقدَّم المساعدات للمستفيدين وفق الضوابط التالية: 1. يجب أن يكون المستفيد مسجلاً في قاعدة بيانات الجمعية ومُحقَّق منه. 2. تُصدر وثيقة استفادة رسمية لكل مساعدة. 3. يوقع المستفيد بالاستلام مع بصمة الإبهام. 4. يُوقع رئيس المكتب وأمين المال على الوثيقة. 5. لا تُمنح أي مساعدة بدون وثيقة رسمية موقعة. 6. تُحفظ نسخة من وثائق الاستفادة في أرشيف الجمعية لمدة لا تقل عن 5 سنوات.', 'financial', true, 15),
(5, 'النظام الانضباطي والأخلاقي', 16, 'المبادئ الأخلاقية', 'يلتزم جميع أعضاء وإطارات الجمعية بالمبادئ التالية: 1. النزاهة والأمانة في جميع التعاملات. 2. احترام كرامة المستفيدين وصون خصوصياتهم. 3. عدم الإفصاح عن بيانات المستفيدين أو أحوالهم المادية لأي طرف خارجي. 4. نبذ كل أشكال التمييز والمحاباة والمحسوبية. 5. تغليب مصلحة الجمعية على المصالح الشخصية. 6. الابتعاد عن كل تصرف يسيء لسمعة الجمعية. 7. التعامل بالمساواة مع جميع المستفيدين دون النظر لانتمائهم الجهوي أو السياسي أو الديني.', 'ethical', true, 16),
(5, 'النظام الانضباطي والأخلاقي', 17, 'المخالفات والعقوبات', 'تُصنَّف المخالفات وعقوباتها على النحو التالي: المخالفات البسيطة → تحذير كتابي. المخالفات المتوسطة → إنذار رسمي أو إيقاف مؤقت. المخالفات الجسيمة → الفصل النهائي: اختلاس أموال الجمعية أو التلاعب بها، إفشاء أسرار المستفيدين أو بياناتهم الخاصة، التصرف بما يضر بمصالح الجمعية أو سمعتها، قبول رشاوى أو مكافآت مقابل تسهيل مساعدات، استغلال موارد الجمعية لأغراض شخصية.', 'disciplinary', true, 17),
(5, 'النظام الانضباطي والأخلاقي', 18, 'إجراءات التأديب', 'تسير إجراءات التأديب وفق الخطوات التالية: 1. رفع تقرير كتابي للمكتب التنفيذي عن المخالفة. 2. استدعاء العضو المخالف كتابياً للاستماع إليه. 3. منح العضو مهلة 15 يوماً لتقديم دفاعه. 4. مداولة المكتب التنفيذي واتخاذ القرار بالأغلبية. 5. تبليغ العضو بالقرار كتابياً. 6. حق العضو في الطعن أمام الجمعية العامة خلال 30 يوماً من تاريخ التبليغ.', 'disciplinary', false, 18),
(6, 'تنظيم الاجتماعات والمداولات', 19, 'اجتماعات المكتب التنفيذي', 'ينعقد المكتب التنفيذي وفق الضوابط التالية: 1. اجتماع دوري شهري على الأقل. 2. يدعو الرئيس للاجتماع بإشعار مكتوب قبل 48 ساعة على الأقل. 3. النصاب القانوني: أكثر من نصف الأعضاء. 4. القرارات بالأغلبية البسيطة، وعند التعادل يرجح صوت الرئيس. 5. يُحرَّر محضر لكل اجتماع ويُوقَّع من الرئيس والكاتب العام. 6. يُحتفظ بمحاضر الاجتماعات في سجل خاص.', 'organizational', false, 19),
(6, 'تنظيم الاجتماعات والمداولات', 20, 'آداب الاجتماعات', 'يلتزم المشاركون في اجتماعات الجمعية بما يلي: 1. الالتزام بمواعيد الاجتماعات وعدم التأخر. 2. إيقاف الهواتف أو ضبطها على الصامت. 3. الاستئذان قبل الكلام وعدم مقاطعة الآخرين. 4. الالتزام ببنود جدول الأعمال. 5. التعبير بأسلوب راقٍ بعيد عن الإساءة والانفعال. 6. احترام القرارات المتخذة بالأغلبية حتى ولو خالفها العضو في التصويت. 7. كتمان ما يُطلب من المداولات سرية.', 'ethical', false, 20),
(7, 'الفروع البلدية والتنسيق', 21, 'إنشاء الفروع البلدية', 'يجوز إنشاء فروع بلدية للجمعية وفق الشروط التالية: 1. تقديم طلب كتابي للمكتب التنفيذي الولائي. 2. توفر عدد كافٍ من الأعضاء (5 أعضاء كحد أدنى). 3. الحصول على موافقة المكتب التنفيذي الولائي. 4. يعمل الفرع البلدي تحت إشراف المكتب الولائي. 5. يُعيَّن رئيس المكتب البلدي بقرار من المكتب الولائي.', 'organizational', false, 21),
(7, 'الفروع البلدية والتنسيق', 22, 'علاقة الفرع بالمكتب الولائي', 'تنظم العلاقة بين الفرع والمكتب الولائي وفق ما يلي: 1. يرفع الفرع تقريراً شهرياً للمكتب الولائي. 2. لا يجوز للفرع التصرف في أموال تتجاوز الحد المقرر دون إذن الولائي. 3. يلتزم الفرع بالخطة السنوية للجمعية الأم. 4. تُعقد اجتماعات تنسيقية دورية بين الفروع والمكتب الولائي (كل 3 أشهر على الأقل). 5. بيانات كل فرع سرية وخاصة به ولا يطلع عليها الفرع الآخر إلا المكتب الولائي.', 'organizational', true, 22),
(8, 'ضوابط استخدام المنصة الرقمية', 23, 'مبدأ السرية الرقمية', 'يلتزم كل مستخدم للمنصة الرقمية لجمعية غيث بما يلي: 1. حفظ كلمة السر الخاصة وعدم مشاركتها مع أي شخص. 2. عدم الوصول لبيانات تتجاوز صلاحياته المحددة. 3. الإبلاغ الفوري عن أي خلل أمني أو اختراق. 4. عدم تصوير أو نسخ البيانات الحساسة. 5. تسجيل الخروج عند الانتهاء من الاستخدام. 6. عدم فتح المنصة على أجهزة مشتركة أو عامة.', 'ethical', true, 23),
(8, 'ضوابط استخدام المنصة الرقمية', 24, 'صلاحيات الوصول وحدودها', 'تُحدَّد صلاحيات الوصول للمنصة كما يلي: رئيس الجمعية ونائبه وأمين المال: وصول كامل لجميع البيانات والسجلات. أعضاء المكتب الولائي: وصول للملفات الإدارية دون السجلات المالية. رئيس المكتب البلدي: وصول لبيانات فرعه فقط دون غيره. المتطوعون والمحسنون والمستفيدون: وصول لحساباتهم الشخصية فقط. يُعدّ أي تجاوز للصلاحيات مخالفة تأديبية جسيمة.', 'disciplinary', true, 24),
(9, 'أحكام ختامية ومتفرقة', 25, 'تعديل القانون الداخلي', 'لا يجوز تعديل هذا القانون الداخلي إلا بـ: 1. طلب كتابي مقدم من ثلث الأعضاء على الأقل. 2. إدراج التعديل في جدول أعمال الجمعية العامة. 3. المصادقة بأغلبية الثلثين من الأعضاء الحاضرين. 4. إشعار الجهات الوصية بالتعديل خلال 30 يوماً.', 'organizational', false, 25),
(9, 'أحكام ختامية ومتفرقة', 26, 'النص المرجعي', 'في حالة الخلاف في تفسير أي مادة من هذا القانون الداخلي، يُرجع إلى: 1. القانون الأساسي للجمعية. 2. القانون رقم 12-06 المتعلق بالجمعيات. 3. قرار المكتب التنفيذي بالأغلبية. يُطبَّق هذا القانون اعتباراً من تاريخ المصادقة عليه من الجمعية العامة.', 'organizational', false, 26);
